use atlas_joined_probe::{Source,build_sources,search};
use atlas_llama_probe::Encoder;
#[test] fn description_title_filter_and_rebuild(){
 let d=std::env::temp_dir().join(format!("atlas-sem-contract-{}",std::process::id()));
 let model=Encoder::start("/private/tmp/atlas-llama-bin/llama-b12001/llama-server","/private/tmp/atlas-embeddinggemma-bf16.gguf").unwrap();
 let docs=[Source{id:"a",title:"Огород",body:"Помидоры поливают утром.",description:""},Source{id:"b",title:"Архив",body:"",description:"😀 Красный велосипед на чердаке."},Source{id:"c",title:"Летняя фотография",body:"",description:""}];
 build_sources(&model,&docs,&d).unwrap();
 let found=search(&model,&d,"красный велосипед",Some(&["b"]),10).unwrap();assert!(!found.is_empty());let f=&found[0];assert_eq!(f["field"],"description");let chars:Vec<char>=docs[1].description.chars().collect();let slice:String=chars[f["start"].as_u64().unwrap() as usize..f["end"].as_u64().unwrap() as usize].iter().collect();assert_eq!(slice,f["text"].as_str().unwrap());
 assert!(!search(&model,&d,"Летняя фотография",Some(&["c"]),10).unwrap().is_empty());
 assert!(search(&model,&d,"велосипед",Some(&[]),10).unwrap().is_empty());assert!(!search(&model,&d,"велосипед",None,10).unwrap().is_empty());
 let docs2=[Source{id:"a",title:"Огород",body:"Только сливы.",description:""}];build_sources(&model,&docs2,&d).unwrap();drop(model);let model=Encoder::start("/private/tmp/atlas-llama-bin/llama-b12001/llama-server","/private/tmp/atlas-embeddinggemma-bf16.gguf").unwrap();let after=search(&model,&d,"велосипед",None,20).unwrap();assert!(after.iter().all(|x|x["id"]=="a"));assert!(search(&model,&d,"велосипед",Some(&["b"]),10).unwrap().is_empty());std::fs::remove_dir_all(d).unwrap();
}
#[test] fn prepared_generation_is_invisible_until_publish(){use atlas_joined_probe::{prepare_sources,publish_sources};let d=std::env::temp_dir().join(format!("atlas-prepared-{}",std::process::id()));let model=Encoder::start("/private/tmp/atlas-llama-bin/llama-b12001/llama-server","/private/tmp/atlas-embeddinggemma-bf16.gguf").unwrap();let old=[Source{id:"old",title:"старое",body:"Исходный текст",description:""}];build_sources(&model,&old,&d).unwrap();let before=std::fs::read_to_string(d.join("current")).unwrap();let new=[Source{id:"new",title:"новое",body:"Новый текст",description:""}];let generation=prepare_sources(&model,&new,&d).unwrap();assert_eq!(std::fs::read_to_string(d.join("current")).unwrap(),before);let old_result=search(&model,&d,"текст",None,10).unwrap();assert!(old_result.iter().all(|r|r["id"]=="old"));publish_sources(&d,&generation).unwrap();let result=search(&model,&d,"текст",None,10).unwrap();assert!(result.iter().all(|r|r["id"]=="new"));std::fs::remove_dir_all(d).unwrap();}
#[test] fn unchanged_vectors_are_reused(){let d=std::env::temp_dir().join(format!("atlas-reuse-{}",std::process::id()));let m=Encoder::start("/private/tmp/atlas-llama-bin/llama-b12001/llama-server","/private/tmp/atlas-embeddinggemma-bf16.gguf").unwrap();let a=[Source{id:"a",title:"Сад",body:"Полив утром",description:"Заметка"},Source{id:"b",title:"Дом",body:"Где ключи",description:""}];build_sources(&m,&a,&d).unwrap();let gen=std::fs::read_to_string(d.join("current")).unwrap();let meta:serde_json::Value=serde_json::from_slice(&std::fs::read(d.join(gen.trim()).join("metadata.json")).unwrap()).unwrap();assert_eq!(meta["encoded_count"].as_u64(),Some(3));let b=[Source{id:"a",title:"Сад",body:"Полив вечером",description:"Заметка"},Source{id:"b",title:"Дом",body:"Где ключи",description:""}];build_sources(&m,&b,&d).unwrap();let gen=std::fs::read_to_string(d.join("current")).unwrap();let meta:serde_json::Value=serde_json::from_slice(&std::fs::read(d.join(gen.trim()).join("metadata.json")).unwrap()).unwrap();assert_eq!(meta["encoded_count"].as_u64(),Some(1));let generation=gen.trim();let path=d.join(generation).join("metadata.json");let mut invalid=meta;invalid["key"]=serde_json::json!("wrong model");std::fs::write(path,serde_json::to_vec(&invalid).unwrap()).unwrap();build_sources(&m,&b,&d).unwrap();let gen=std::fs::read_to_string(d.join("current")).unwrap();let meta:serde_json::Value=serde_json::from_slice(&std::fs::read(d.join(gen.trim()).join("metadata.json")).unwrap()).unwrap();assert_eq!(meta["encoded_count"].as_u64(),Some(3));std::fs::remove_dir_all(d).unwrap();}
